#!/bin/bash
# Builds the binary release archive in a manylinux_2_28 container, with the
# same settings as the PyPI wheels (cmake/WheelConfig.cmake). The archive
# contains libssqp.a, the ssqpy module, the headers, the examples and the
# Pinocchio and HPIPM prebuilt packages
#
# Usage: build-release-archive.sh <project dir> <archive name> <output dir>
set -euo pipefail

project=$(realpath "$1")
name=$2
out=$(realpath "$3")
work=/tmp/ssqp-release
python=/opt/python/cp312-cp312/bin/python
stage="$work/$name"

bash "$project/.github/scripts/build-wheel-deps.sh" "$project"

# The stubs are generated by importing ssqpy, which needs NumPy
"$python" -m pip install numpy

# Development.SABIModule makes ssqpy use the stable ABI, as in the cp312 wheel
cmake -S "$project" -B "$work/build" \
    -C "$project/cmake/WheelConfig.cmake" \
    -DBUILD_TESTS=OFF \
    -DSSQP_PREBUILT_PINOCCHIO_DIR=/opt/ssqp-deps/pinocchio \
    -DSSQP_PREBUILT_HPIPM_DIR=/opt/ssqp-deps/hpipm \
    -DPython_EXECUTABLE="$python" \
    -DSKBUILD_SABI_COMPONENT=Development.SABIModule
cmake --build "$work/build" --target ssqp ssqpy -j"$(nproc)"

rm -rf "$stage"
mkdir -p "$stage/lib" "$stage/python" "$stage/prebuilt"
cp -r "$project/include" "$project/examples" "$stage/"
# The headers include the template implementations in src/ and the Tracy
# and JSON headers
(cd "$project" && find src -name "*.tpp" | cp --parents -t "$stage" -- $(cat))
(cd "$project" && cp --parents -r -t "$stage" \
    external/tracy/public external/tracy/LICENSE \
    external/json/single_include external/json/LICENSE.MIT)
cp "$project/LICENSE" "$project/THIRD_PARTY_NOTICES.md" "$project/README.md" "$stage/"
cp "$work/build/lib/libssqp.a" "$stage/lib/"
cp -r "$work/build/bindings/." "$stage/python/"
cp -r /opt/ssqp-deps/pinocchio /opt/ssqp-deps/hpipm "$stage/prebuilt/"

mkdir -p "$out"
tar czf "$out/$name.tar.gz" -C "$work" "$name"
